import java.util.*;

public class Main {
    static final class Team {
        private final List<String> members;
        public Team(List<String> members) {
            this.members = new ArrayList<>(members);
        }
        public List<String> getMembers() {
            return members;
        }
    }
    public static void main(String[] args) {
        List<String> src = new ArrayList<>(List.of("ann"));
        Team t = new Team(src);
        src.add("bob");
        t.getMembers().add("eve");
        System.out.println(t.getMembers());
    }
}

import java.io.*;

public class Main {
    static class User implements Serializable {
        private static final long serialVersionUID = 1L;
        private final String name;
        private transient String password;
        User(String name, String password) { this.name = name; this.password = password; }
        public String toString() { return name + ":" + password; }
    }
    public static void main(String[] args) throws Exception {
        ByteArrayOutputStream bos = new ByteArrayOutputStream();
        try (ObjectOutputStream out = new ObjectOutputStream(bos)) {
            out.writeObject(new User("alice", "s3cret"));
        }
        try (ObjectInputStream in = new ObjectInputStream(
                new ByteArrayInputStream(bos.toByteArray()))) {
            System.out.println(in.readObject());
        }
    }
}

public class Main {
    static class Account {
        private int balance;
        public Account(int initial) {
            if (!isValid(initial)) throw new IllegalArgumentException("invalid");
            balance = initial;
        }
        public boolean isValid(int amount) { return amount >= 0; }
        int getBalance() { return balance; }
    }
    static class Evil extends Account {
        Evil() { super(-100); }
        @Override public boolean isValid(int amount) { return true; }
    }
    public static void main(String[] args) {
        System.out.println(new Evil().getBalance());
    }
}
